window.GH3_DATA = window.GH3_DATA || {};
window.GH3_DATA.flashcards = [  {"id": "r1", "deck": "Responsible Use", "tag": "Fairness", "front": "Fairness principle", "back": "<p><strong>Fairness</strong> means GitHub Copilot and related AI systems should treat groups equitably and avoid advantaging or disadvantaging people based on demographic traits.</p><p class=\"faint\">Do not confuse with inclusiveness: fairness is about equitable outcomes and treatment; inclusiveness is about whether everyone can use the system. Giveaway words: bias, demographic, equitable, disparate impact.</p>"},
  {"id": "r2", "deck": "Responsible Use", "tag": "Reliability", "front": "Reliability and safety principle", "back": "<p><strong>Reliability and safety</strong> means AI systems should behave consistently under expected conditions, be evaluated for harms, and fail safely when something goes wrong.</p><p class=\"faint\">Do not confuse with accountability: reliability is about dependable behavior; accountability is about who is answerable for outcomes. Giveaway words: safe, consistent, testing, harm.</p>"},
  {"id": "r3", "deck": "Responsible Use", "tag": "Privacy", "front": "Privacy and security principle", "back": "<p><strong>Privacy and security</strong> means prompts, code, and personal data should be protected, collected only as appropriate, and handled according to privacy and security commitments.</p><p class=\"faint\">Do not confuse with transparency: privacy protects data; transparency explains how the system works and what limits it has. Giveaway words: personal data, retention, protection, security.</p>"},
  {"id": "r4", "deck": "Responsible Use", "tag": "Inclusiveness", "front": "Inclusiveness principle", "back": "<p><strong>Inclusiveness</strong> means AI tools should be usable by people with different abilities, backgrounds, languages, and needs so the benefits are broadly accessible.</p><p class=\"faint\">Do not confuse with fairness: inclusiveness asks whether users can access and use the tool; fairness asks whether groups are treated equitably by the tool. Giveaway words: accessible, disability, everyone, language.</p>"},
  {"id": "r5", "deck": "Responsible Use", "tag": "Transparency", "front": "Transparency principle", "back": "<p><strong>Transparency</strong> means users should understand when AI is involved, what it can and cannot do, and how to interpret its suggestions responsibly.</p><p class=\"faint\">Do not confuse with accountability: transparency explains the system; accountability assigns responsibility for the system. Giveaway words: disclose, explain, limitations, understand.</p>"},
  {"id": "r6", "deck": "Responsible Use", "tag": "Accountability", "front": "Accountability principle", "back": "<p><strong>Accountability</strong> means people and organizations remain responsible for AI-assisted decisions, including governance, review, and corrective action when harm occurs.</p><p class=\"faint\">Do not confuse with reliability and safety: reliability tests behavior; accountability asks who owns the decision. Giveaway words: responsible, governance, owner, oversight.</p>"},
  {"id": "r7", "deck": "Responsible Use", "tag": "Fairness", "front": "Fairness vs inclusiveness", "back": "<p><strong>Fairness</strong> is the principle most associated with reducing biased or unequal outcomes across groups, while inclusiveness is about broad access and usability.</p><p class=\"faint\">Exam trap: a screen-reader problem is inclusiveness, not fairness. A model suggesting worse code or opportunities for one group than another is fairness.</p>"},
  {"id": "r8", "deck": "Responsible Use", "tag": "Reliability", "front": "Reliability vs transparency", "back": "<p><strong>Reliability and safety</strong> answers whether Copilot output works correctly and safely; transparency answers whether users understand AI involvement and limitations.</p><p class=\"faint\">Exam trap: asking Copilot to explain uncertainty improves transparency, but it does not prove the code is reliable. Tests, review, and validation address reliability.</p>"},
  {"id": "r9", "deck": "Responsible Use", "tag": "Privacy", "front": "Privacy vs security", "back": "<p><strong>Privacy and security</strong> combines two related duties: limiting and protecting sensitive data, and defending systems from unauthorized access or misuse.</p><p class=\"faint\">Do not split the Microsoft principle into two principles on the exam. Giveaway words: prompts, personal data, tenant protection, access controls.</p>"},
  {"id": "r10", "deck": "Responsible Use", "tag": "Inclusiveness", "front": "Inclusiveness vs transparency", "back": "<p><strong>Inclusiveness</strong> focuses on making Copilot usable by a broad range of people; transparency focuses on making Copilot behavior and limitations understandable.</p><p class=\"faint\">Exam trap: documentation that explains limitations is transparency. Keyboard access, screen-reader support, and plain language for varied users are inclusiveness.</p>"},
  {"id": "r11", "deck": "Responsible Use", "tag": "Transparency", "front": "Transparency vs accountability", "back": "<p><strong>Transparency</strong> is about explaining AI behavior and limits; accountability is about humans and organizations being answerable for AI-assisted outcomes.</p><p class=\"faint\">Giveaway words for transparency: explain, disclose, communicate, limitations. Giveaway words for accountability: approve, responsible, governance, audit.</p>"},
  {"id": "r12", "deck": "Responsible Use", "tag": "Accountability", "front": "Accountability vs human oversight", "back": "<p><strong>Accountability</strong> is the principle; human oversight is one way to implement it by requiring review, approval, or the ability to override AI output.</p><p class=\"faint\">Exam trap: human-in-the-loop is not a seventh principle. It is a mitigation that supports accountability and safe operation.</p>"},
  {"id": "r13", "deck": "Responsible Use", "tag": "Limitations", "front": "Code quality and correctness limitation", "back": "<p><strong>Code quality and correctness</strong> is a Copilot limitation category covering errors, security concerns, and misinterpreting code context.</p><p class=\"faint\">Do not confuse with language specificity: code quality is about whether the suggestion is correct and secure, not whether Copilot performs better in one framework than another.</p>"},
  {"id": "r14", "deck": "Responsible Use", "tag": "Limitations", "front": "Language and framework specificity limitation", "back": "<p><strong>Language and framework specificity</strong> means Copilot performance varies by programming language, framework, and how well the technology is represented in training and context.</p><p class=\"faint\">Exam trap: weak suggestions in a niche framework are this category. A syntactically plausible but vulnerable suggestion is code quality and correctness.</p>"},
  {"id": "r15", "deck": "Responsible Use", "tag": "Limitations", "front": "Dependency on training data limitation", "back": "<p><strong>Dependency on training data</strong> means Copilot can reflect bias, outdated practices, and copyright concerns from the data and patterns it learned.</p><p class=\"faint\">Do not confuse with retention or training policy. This limitation is about model behavior caused by training data, not whether a customer prompt is used for future training.</p>"},
  {"id": "r16", "deck": "Responsible Use", "tag": "Limitations", "front": "Complex problem solving limitation", "back": "<p><strong>Complex problem solving</strong> means Copilot may struggle with high-level design, broad architecture, and truly novel creative problem solving.</p><p class=\"faint\">Exam trap: Copilot can help implement pieces, but humans should own architecture and trade-off decisions. Giveaway words: system design, creativity, strategy.</p>"},
  {"id": "r17", "deck": "Responsible Use", "tag": "Bias", "front": "Bias from training data", "back": "<p><strong>Bias from training data</strong> occurs when suggestions reflect skewed, outdated, or inequitable patterns present in source material the model learned from.</p><p class=\"faint\">Do not confuse with prompt injection. Bias is an output-quality and fairness risk; prompt injection is an attack that tries to override instructions.</p>"},
  {"id": "r18", "deck": "Responsible Use", "tag": "Bias", "front": "Bias from user context", "back": "<p><strong>Bias from user context</strong> can appear when open files, filenames, comments, or examples steer Copilot toward an incomplete or skewed solution.</p><p class=\"faint\">Exam trap: context can improve answers and also mislead them. Keeping relevant files open helps, but irrelevant or biased context can hurt.</p>"},
  {"id": "r19", "deck": "Responsible Use", "tag": "Mitigation", "front": "Mitigating biased suggestions", "back": "<p><strong>Mitigating biased suggestions</strong> means reviewing outputs, testing across cases, improving context, and rejecting or rewriting suggestions that encode unfair assumptions.</p><p class=\"faint\">Do not confuse mitigation with blind acceptance. Giveaway words: review, diverse test cases, representative examples, human judgment.</p>"},
  {"id": "r20", "deck": "Responsible Use", "tag": "Validation", "front": "Validate AI output", "back": "<p><strong>Validate AI output</strong> means treat Copilot suggestions as drafts that require review, tests, security checks, and confirmation against project requirements.</p><p class=\"faint\">Exam trap: Copilot can accelerate work, but it does not transfer responsibility away from the developer. Giveaway words: verify, review, run tests, inspect.</p>"},
  {"id": "r21", "deck": "Responsible Use", "tag": "Oversight", "front": "Human oversight", "back": "<p><strong>Human oversight</strong> means a person remains in the loop to approve, reject, modify, or escalate Copilot output before it affects users or production systems.</p><p class=\"faint\">Do not confuse with automation. Agentic features can do more work, but responsible use still requires boundaries and human review.</p>"},
  {"id": "r22", "deck": "Responsible Use", "tag": "Security", "front": "Security review of suggestions", "back": "<p><strong>Security review</strong> means checking AI-generated code for vulnerabilities such as injection flaws, unsafe defaults, and mishandled secrets before accepting it.</p><p class=\"faint\">Exam trap: a suggestion that compiles can still be insecure. Giveaway words: XSS, SQL injection, secret, vulnerability.</p>"},
  {"id": "r23", "deck": "Responsible Use", "tag": "Copyright", "front": "Copyright and public code concern", "back": "<p><strong>Copyright concern</strong> is a risk from training-data dependency and matching public code, so organizations may use Suggestions matching public code and code referencing safeguards.</p><p class=\"faint\">Do not assert an exact public-code-matching threshold as the point of the question. The safe exam idea is the safeguard, not the disputed interpretation.</p>"},
  {"id": "r24", "deck": "Responsible Use", "tag": "Operation", "front": "Operate responsibly", "back": "<p><strong>Operate responsibly</strong> means monitor AI-assisted workflows after rollout, collect feedback, enforce policies, and update practices as product behavior and risk change.</p><p class=\"faint\">Do not confuse with a one-time launch review. Giveaway words: ongoing monitoring, feedback loop, governance, operate stage.</p>"},
  {"id": "r25", "deck": "Responsible Use", "tag": "Ethics", "front": "Ethical use", "back": "<p><strong>Ethical use</strong> means applying Copilot in ways that respect people, data, law, organizational policy, and the developer's duty to verify results.</p><p class=\"faint\">Exam trap: ethics is broader than privacy. It also includes fairness, safety, transparency, inclusiveness, and accountability.</p>"},
  {"id": "r26", "deck": "Responsible Use", "tag": "Risk", "front": "Potential harms and mitigations", "back": "<p><strong>Potential harms and mitigations</strong> pairs each AI risk, such as bias, insecure code, hallucination, or privacy exposure, with controls such as review, testing, exclusions, and policy.</p><p class=\"faint\">Giveaway words: identify, measure, mitigate, operate. Do not stop at naming a harm; responsible AI questions often ask for the matching control.</p>"},
  {"id": "i1", "deck": "Copilot in the IDE", "tag": "Inline", "front": "Inline suggestions", "back": "<p><strong>Inline suggestions</strong> are Copilot completions shown directly in the editor at the cursor, usually rendered as ghost text that you can accept, reject, or cycle through.</p><p class=\"faint\">Do not confuse with next edit suggestions. Inline suggestions complete the current location; next edit suggestions predict where you may edit next.</p>"},
  {"id": "i2", "deck": "Copilot in the IDE", "tag": "Ghost text", "front": "Ghost text", "back": "<p><strong>Ghost text</strong> is the editor rendering of an inline suggestion, appearing as dim text in the code file before you accept it.</p><p class=\"faint\">Exam trap: ghost text is not a separate Copilot feature or mode. It is how inline suggestions appear in the IDE.</p>"},
  {"id": "i3", "deck": "Copilot in the IDE", "tag": "Next edit", "front": "Next edit suggestions", "back": "<p><strong>Next edit suggestions</strong> predict the likely location and shape of your next change after observing recent edits and surrounding code.</p><p class=\"faint\">Do not confuse with inline suggestions. Giveaway words: next location, after a recent edit, predict the next change.</p>"},
  {"id": "i4", "deck": "Copilot in the IDE", "tag": "FIM", "front": "Fill-in-the-Middle (FIM)", "back": "<p><strong>Fill-in-the-Middle (FIM)</strong> is the prompt-building technique that considers code before and after the cursor so Copilot can complete the middle of a file.</p><p class=\"faint\">Exam trap: FIM is named in the official study material even if it is less visible in product docs. Giveaway words: before and after cursor.</p>"},
  {"id": "i5", "deck": "Copilot in the IDE", "tag": "Chat", "front": "Ask mode", "back": "<p><strong>Ask mode</strong> is the chat mode for questions, explanations, planning, and guidance without directly applying broad edits to the workspace.</p><p class=\"faint\">Do not confuse with Edit mode or Agent mode. Ask is best when you want an answer or explanation, not Copilot to modify files autonomously.</p>"},
  {"id": "i6", "deck": "Copilot in the IDE", "tag": "Edit mode", "front": "Edit mode", "back": "<p><strong>Edit mode</strong> lets Copilot apply requested changes across one or more files while the developer reviews and accepts the edits.</p><p class=\"faint\">The old study-guide name was Copilot Edits; current docs call it Edit mode. Do not mark the old name as current unless framed as renamed history.</p>"},
  {"id": "i7", "deck": "Copilot in the IDE", "tag": "Agent mode", "front": "Agent mode", "back": "<p><strong>Agent mode</strong> is the IDE mode where Copilot can plan and carry out multi-step coding tasks with tools, terminal commands, and file edits under developer supervision.</p><p class=\"faint\">Do not confuse with Copilot cloud agent. Agent mode runs in the IDE session; the cloud agent runs autonomously on GitHub infrastructure.</p>"},
  {"id": "i8", "deck": "Copilot in the IDE", "tag": "Mode contrast", "front": "Ask vs Edit mode", "back": "<p><strong>Ask mode</strong> answers and explains, while Edit mode makes targeted code changes that the developer reviews.</p><p class=\"faint\">Exam trap: if the task is \"explain this error,\" choose Ask. If the task is \"update these files to use the new API,\" choose Edit mode.</p>"},
  {"id": "i9", "deck": "Copilot in the IDE", "tag": "Mode contrast", "front": "Edit mode vs Agent mode", "back": "<p><strong>Edit mode</strong> is for directed edits, while Agent mode is for broader multi-step tasks that may need planning, tool use, and iteration.</p><p class=\"faint\">Giveaway words for Agent mode: run tests, inspect failures, iterate, multi-step. Giveaway words for Edit mode: apply these changes, update selected files.</p>"},
  {"id": "i10", "deck": "Copilot in the IDE", "tag": "Mode contrast", "front": "Agent mode vs Copilot cloud agent", "back": "<p><strong>Agent mode</strong> is an IDE feature; Copilot cloud agent is a GitHub-hosted autonomous agent for delegated work.</p><p class=\"faint\">Exam trap: both are agentic, but location matters. IDE mode stays in your local development environment; cloud agent runs on GitHub.</p>"},
  {"id": "i11", "deck": "Copilot in the IDE", "tag": "Availability", "front": "Agent mode availability", "back": "<p><strong>Agent mode</strong> is available in supported IDEs but is not available in NeoVim according to the current feature distinctions.</p><p class=\"faint\">Do not assume every editor supports every Copilot feature. NeoVim can support inline suggestions, but not Agent mode.</p>"},
  {"id": "i12", "deck": "Copilot in the IDE", "tag": "Availability", "front": "Edit mode availability", "back": "<p><strong>Edit mode</strong> is supported in VS Code and JetBrains and is not supported in Visual Studio, Eclipse, or Xcode.</p><p class=\"faint\">Exam trap: Visual Studio support for chat or completions does not imply support for Edit mode. Match the feature to the IDE.</p>"},
  {"id": "i13", "deck": "Copilot in the IDE", "tag": "Slash commands", "front": "Slash commands", "back": "<p><strong>Slash commands</strong> are short chat commands that invoke common Copilot actions or workflows from the chat interface.</p><p class=\"faint\">Do not confuse slash commands with chat participants. Slash commands describe the action; participants route the request to a domain or context.</p>"},
  {"id": "i14", "deck": "Copilot in the IDE", "tag": "Participants", "front": "Chat participants", "back": "<p><strong>Chat participants</strong> scope a Copilot Chat request to a specialized context or capability, such as workspace-focused help.</p><p class=\"faint\">Do not confuse with slash commands or variables. Participants answer \"who should handle this context?\" while slash commands answer \"what action should run?\"</p>"},
  {"id": "i15", "deck": "Copilot in the IDE", "tag": "Variables", "front": "Chat variables", "back": "<p><strong>Chat variables</strong> insert specific context into a prompt, such as selected code, an open file, or workspace information.</p><p class=\"faint\">Exam trap: variables are about supplying context. They do not change Copilot policy, model selection, or subscription plan.</p>"},
  {"id": "i16", "deck": "Copilot in the IDE", "tag": "Prompt files", "front": "Prompt files in IDEs", "back": "<p><strong>Prompt files</strong> are reusable prompts stored under .github/prompts/*.prompt.md and supported in VS Code and Visual Studio, with preview support in JetBrains and Xcode.</p><p class=\"faint\">Do not confuse with custom instructions. Prompt files are invoked when needed; instructions are automatically supplied as guidance.</p>"},
  {"id": "i17", "deck": "Copilot in the IDE", "tag": "Instructions", "front": "Custom instructions in the IDE", "back": "<p><strong>Custom instructions</strong> provide standing guidance to Copilot about repository conventions, style, or rules, while Copilot may still behave non-deterministically.</p><p class=\"faint\">Exam trap: instructions improve consistency but are not guaranteed to be followed identically every time.</p>"},
  {"id": "i18", "deck": "Copilot in the IDE", "tag": "CLI", "front": "Standalone GitHub Copilot CLI", "back": "<p><strong>GitHub Copilot CLI</strong> is the standalone Copilot command-line experience for interactive sessions, scripting, file management, and programmatic prompts.</p><p class=\"faint\">Current name is standalone GitHub Copilot CLI. The old gh copilot CLI extension wording should only appear as renamed history, not as the current product name.</p>"},
  {"id": "i19", "deck": "Copilot in the IDE", "tag": "CLI", "front": "Copilot CLI modes", "back": "<p><strong>Copilot CLI</strong> supports interactive use and programmatic prompting, including -p or --prompt, and has a plan mode that can be cycled with Shift+Tab.</p><p class=\"faint\">Do not confuse the standalone CLI with IDE chat. Giveaway words: terminal, script generation, sessions, PowerShell, WSL.</p>"},
  {"id": "i20", "deck": "Copilot in the IDE", "tag": "CLI", "front": "Copilot CLI platforms", "back": "<p><strong>GitHub Copilot CLI</strong> runs on Linux, macOS, and Windows, including PowerShell and WSL on Windows.</p><p class=\"faint\">Exam trap: platform support for the CLI is separate from feature support inside a particular IDE.</p>"},
  {"id": "i21", "deck": "Copilot in the IDE", "tag": "Mobile", "front": "Copilot in GitHub Mobile", "back": "<p><strong>Copilot in GitHub Mobile</strong> lets users access Copilot Chat and GitHub context from the mobile app, with content exclusion support in public preview.</p><p class=\"faint\">Do not confuse Mobile with the code editor. Chat outside the editor has different retention guidance than editor completions.</p>"},
  {"id": "i22", "deck": "Copilot in the IDE", "tag": "Model picker", "front": "Independent model selection", "back": "<p><strong>Independent model selection</strong> means inline suggestions, next edit suggestions, and Chat each have their own model selection; changing one does not change the others.</p><p class=\"faint\">Exam trap: model settings are not global across all Copilot experiences. Also, do not study specific model version numbers.</p>"},
  {"id": "i23", "deck": "Copilot in the IDE", "tag": "Model picker", "front": "Auto model selection", "back": "<p><strong>Auto model selection</strong> lets Copilot choose the model automatically and is the only model option for Copilot Free and Copilot Student.</p><p class=\"faint\">Do not confuse Auto model selection with an LTS fallback. Auto is a selectable behavior; LTS is used if no other model is available.</p>"},
  {"id": "i24", "deck": "Copilot in the IDE", "tag": "Filters", "front": "Filters apply to every model", "back": "<p><strong>Content filters</strong> apply regardless of which model is chosen, including harmful-content filtering and public-code matching when enabled.</p><p class=\"faint\">Exam trap: switching models does not change data collection and usage policy and does not bypass safety filters.</p>"},
  {"id": "i25", "deck": "Copilot in the IDE", "tag": "Enablement", "front": "Enabling Copilot in the IDE", "back": "<p><strong>Enabling Copilot in the IDE</strong> requires the appropriate Copilot access, client support, and enabled feature policies for the IDE experience you want to use.</p><p class=\"faint\">Do not infer one feature from another. An organization may allow the Copilot app but govern the Copilot CLI with a separate client policy.</p>"},
  {"id": "i26", "deck": "Copilot in the IDE", "tag": "Skills", "front": "IDE chat skills and Free plan", "back": "<p><strong>Copilot Chat skills in IDEs</strong> are not available in Copilot Free according to the feature distinctions in the brief.</p><p class=\"faint\">Exam trap: all plans include Copilot CLI and the Copilot app, but not every plan includes every IDE chat capability.</p>"},
  {"id": "p1", "deck": "Copilot on the Platform", "tag": "Cloud agent", "front": "Copilot cloud agent", "back": "<p><strong>Copilot cloud agent</strong> is the current name for GitHub's autonomous coding agent that runs delegated work on GitHub infrastructure.</p><p class=\"faint\">It was formerly called Copilot coding agent and was renamed April 1, 2026. Do not confuse it with IDE Agent mode, which runs in the developer's IDE.</p>"},
  {"id": "p2", "deck": "Copilot on the Platform", "tag": "Cloud agent", "front": "Cloud agent vs IDE Agent mode", "back": "<p><strong>Copilot cloud agent</strong> runs autonomously on GitHub, while Agent mode is an IDE feature for multi-step local development work.</p><p class=\"faint\">Exam trap: both are agentic. Giveaway words for cloud agent: delegated task, GitHub-hosted, autonomous, pull request.</p>"},
  {"id": "p3", "deck": "Copilot on the Platform", "tag": "Cloud agent", "front": "Enterprise access to cloud agent", "back": "<p><strong>Copilot cloud agent</strong> has a special enterprise policy model where enterprises select exactly which organizations get access.</p><p class=\"faint\">Do not assume the usual enable, disable, or let organizations decide pattern applies to every policy. Cloud agent is the named exception.</p>"},
  {"id": "p4", "deck": "Copilot on the Platform", "tag": "Code review", "front": "Copilot code review", "back": "<p><strong>Copilot code review</strong> uses Copilot to review pull requests and code changes, applying repository and organization instructions where supported.</p><p class=\"faint\">Do not confuse with Copilot Autofix. Code review comments on changes; Autofix generates fixes for CodeQL code scanning alerts.</p>"},
  {"id": "p5", "deck": "Copilot on the Platform", "tag": "Code review", "front": "Custom review standards", "back": "<p><strong>Custom review standards</strong> can be supplied through instructions files so Copilot code review follows repository-specific expectations.</p><p class=\"faint\">Exam trap: on pull requests, Copilot reads instructions and skills from the head branch, not the base branch.</p>"},
  {"id": "p6", "deck": "Copilot on the Platform", "tag": "Pull requests", "front": "Pull request summaries", "back": "<p><strong>Pull request summaries</strong> are assistive Copilot features that summarize PR changes to reduce review overhead and improve reviewer context.</p><p class=\"faint\">Do not confuse summaries with code review. A summary explains what changed; code review looks for issues and suggests improvements.</p>"},
  {"id": "p7", "deck": "Copilot on the Platform", "tag": "Spaces", "front": "Copilot Spaces", "back": "<p><strong>Copilot Spaces</strong> are the current customization feature for giving Copilot shared context such as documentation, repositories, and project knowledge.</p><p class=\"faint\">Copilot knowledge bases were retired and replaced by Copilot Spaces. Treat knowledge bases as history or a distractor, not the current answer.</p>"},
  {"id": "p8", "deck": "Copilot on the Platform", "tag": "Spaces", "front": "Spaces vs custom instructions", "back": "<p><strong>Copilot Spaces</strong> provide curated context; custom instructions provide standing behavior guidance such as style or conventions.</p><p class=\"faint\">Exam trap: use Spaces for shared knowledge and documentation context. Use instructions for how Copilot should respond or code.</p>"},
  {"id": "p9", "deck": "Copilot on the Platform", "tag": "MCP", "front": "MCP servers", "back": "<p><strong>MCP servers</strong> are the current extensibility mechanism for connecting Copilot to external tools, data sources, and workflows.</p><p class=\"faint\">GitHub App-based Copilot Extensions were sunset and replaced by MCP servers. Do not present Copilot Extensions as a live GitHub platform feature.</p>"},
  {"id": "p10", "deck": "Copilot on the Platform", "tag": "MCP", "front": "MCP policy scope", "back": "<p><strong>MCP server policy</strong> applies where MCP support is generally available and does not control the GitHub MCP server inside third-party hosts like Cursor, Windsurf, or Claude.</p><p class=\"faint\">Exam trap: an enterprise setting inside GitHub does not automatically govern every external host that can speak MCP.</p>"},
  {"id": "p11", "deck": "Copilot on the Platform", "tag": "Extensions", "front": "Client-side VS Code extensions unaffected", "back": "<p><strong>Client-side VS Code Copilot extensions</strong> are unaffected by the sunset of GitHub App-based Copilot Extensions and remain supported.</p><p class=\"faint\">The retirement applies to GitHub App-based Copilot Extensions. Do not blur that with VS Code client extensions.</p>"},
  {"id": "p12", "deck": "Copilot on the Platform", "tag": "Custom agents", "front": "Custom agents", "back": "<p><strong>Custom agents</strong> are customization features that let teams define specialized agent behavior for particular workflows or repositories.</p><p class=\"faint\">Do not confuse custom agents with Copilot cloud agent. Custom agents define behavior; the cloud agent is a GitHub-hosted autonomous coding agent.</p>"},
  {"id": "p13", "deck": "Copilot on the Platform", "tag": "Subagents", "front": "Subagents", "back": "<p><strong>Subagents</strong> are specialized agents used to divide or focus work so context can be optimized for different parts of a task.</p><p class=\"faint\">Exam trap: subagents are a customization and agentic workflow concept, not a replacement for organization policies or content exclusions.</p>"},
  {"id": "p14", "deck": "Copilot on the Platform", "tag": "Agent skills", "front": "Agent skills", "back": "<p><strong>Agent skills</strong> are reusable capabilities that can be made available to agents as part of Copilot customization.</p><p class=\"faint\">Do not confuse skills with prompt files. Skills add capabilities; prompt files store reusable prompts.</p>"},
  {"id": "p15", "deck": "Copilot on the Platform", "tag": "Hooks", "front": "Hooks", "back": "<p><strong>Hooks</strong> are JSON-based automation points stored at .github/hooks/*.json for Copilot-related workflows such as custom logging.</p><p class=\"faint\">Exam trap: audit logs do not capture local prompts. Some organizations use hooks for custom CLI event logging instead.</p>"},
  {"id": "p16", "deck": "Copilot on the Platform", "tag": "Policies", "front": "Organization-wide policy management", "back": "<p><strong>Organization-wide policy management</strong> lets organization owners control feature availability, privacy settings, Copilot code review, and related Copilot behavior for members.</p><p class=\"faint\">Do not confuse policies with instructions. Policies enforce access or settings; instructions guide Copilot behavior and rank lower at organization level.</p>"},
  {"id": "p17", "deck": "Copilot on the Platform", "tag": "Policies", "front": "Enterprise AI controls", "back": "<p><strong>Enterprise AI controls</strong> are enterprise-level Copilot settings, including policies on the AI controls tab and settings for enterprise-assigned users.</p><p class=\"faint\">Exam trap: an enterprise can often enable, disable, or let organizations decide, but policy conflict rules depend on enterprise boundaries.</p>"},
  {"id": "p18", "deck": "Copilot on the Platform", "tag": "Policies", "front": "Independent client policies", "back": "<p><strong>Independent client policies</strong> mean the Copilot app and Copilot CLI can be governed separately, so an organization can allow one and not the other.</p><p class=\"faint\">Do not assume allowing Copilot in one client enables it everywhere. Giveaway words: separate client policies, app vs CLI.</p>"},
  {"id": "p19", "deck": "Copilot on the Platform", "tag": "Audit", "front": "Audit log Copilot events", "back": "<p><strong>Copilot audit log events</strong> include changes to Copilot settings, policies, license grants and removals, plus agent activity on the GitHub website.</p><p class=\"faint\">Do not confuse this with prompt logging. Audit logs do not include local client session data such as prompts sent to Copilot locally.</p>"},
  {"id": "p20", "deck": "Copilot on the Platform", "tag": "Subscriptions", "front": "Subscription management API", "back": "<p><strong>Subscription management</strong> can be handled through organization and enterprise settings and by using the REST API for subscription management.</p><p class=\"faint\">Exam trap: subscription administration is a platform administrator capability, not an IDE feature.</p>"},
  {"id": "p21", "deck": "Copilot on the Platform", "tag": "Spark", "front": "Copilot Spark retirement", "back": "<p><strong>Copilot Spark</strong> is retired as of August 31, 2026; already-deployed apps continue to work, but it should not be taught as a live Copilot feature.</p><p class=\"faint\">The study guide still mentions Spark, so recognize it as historical. Replacement direction: build directly with Copilot in VS Code, Copilot CLI, and the GitHub Copilot app.</p>"},
  {"id": "p22", "deck": "Copilot on the Platform", "tag": "GitHub Models", "front": "GitHub Models retirement", "back": "<p><strong>GitHub Models</strong> was the inference service behind Spark's llm() function and retired July 30, 2026.</p><p class=\"faint\">Do not present GitHub Models as a live service for exam-prep content. Its safe role here is retirement history tied to Spark.</p>"},
  {"id": "p23", "deck": "Copilot on the Platform", "tag": "Workspace", "front": "Copilot Workspace retirement", "back": "<p><strong>Copilot Workspace</strong> is retired and absent from current docs.</p><p class=\"faint\">Never state a Workspace sunset date; the brief confirms retirement but marks the exact date unverified. That date is an exam-content trap.</p>"},
  {"id": "p24", "deck": "Copilot on the Platform", "tag": "Extensions", "front": "Copilot Extensions retirement", "back": "<p><strong>Copilot Extensions</strong> were GitHub App-based integrations that were fully sunset November 10, 2025 and replaced by MCP servers.</p><p class=\"faint\">Allowed framing is retirement or history only. The current correct extensibility answer is MCP servers.</p>"},
  {"id": "p25", "deck": "Copilot on the Platform", "tag": "Knowledge bases", "front": "Knowledge bases retirement", "back": "<p><strong>Copilot knowledge bases</strong> were retired November 1, 2025 and replaced by Copilot Spaces.</p><p class=\"faint\">Exam trap: if the question asks for current shared documentation context, choose Spaces, not knowledge bases.</p>"},
  {"id": "p26", "deck": "Copilot on the Platform", "tag": "Desktop", "front": "Copilot in GitHub Desktop", "back": "<p><strong>Copilot in GitHub Desktop</strong> is an assistive Copilot feature category alongside Chat, inline suggestions, next edit suggestions, and PR summaries.</p><p class=\"faint\">Do not confuse GitHub Desktop support with IDE Agent mode or Copilot cloud agent. It is part of the platform/product surface.</p>"},
  {"id": "p27", "deck": "Copilot on the Platform", "tag": "Copilot app", "front": "GitHub Copilot app", "back": "<p><strong>GitHub Copilot app</strong> is an agentic Copilot surface included with all plans and governed separately from the Copilot CLI by client policies.</p><p class=\"faint\">Exam trap: app policy and CLI policy are independent. A policy can allow one client while blocking another.</p>"},
  {"id": "p28", "deck": "Copilot on the Platform", "tag": "Third-party agents", "front": "Third-party coding agents", "back": "<p><strong>Third-party coding agents</strong> are an agentic feature category in preview, distinct from Copilot cloud agent and custom agents.</p><p class=\"faint\">Do not confuse preview third-party agents with MCP servers. MCP connects tools and context; third-party agents are coding agents.</p>"},
  {"id": "p29", "deck": "Copilot on the Platform", "tag": "Feature groups", "front": "Four current feature groups", "back": "<p><strong>Four current feature groups</strong> are assistive, agentic, customization, and administrator.</p><p class=\"faint\">Giveaway words: inline suggestions are assistive; cloud agent is agentic; Spaces and MCP are customization; policies and audit logs are administrator.</p>"},
  {"id": "p30", "deck": "Copilot on the Platform", "tag": "Current names", "front": "Current platform naming", "back": "<p><strong>Current platform naming</strong> uses Copilot cloud agent, MCP servers, Copilot Spaces, GitHub AI Credits, and Suggestions matching public code.</p><p class=\"faint\">Exam trap: old names may appear in study material. Learn the mapping, but answer with the current name unless the card explicitly asks for history.</p>"},
  {"id": "d1", "deck": "Data & Architecture", "tag": "Lifecycle", "front": "Seven-step request lifecycle", "back": "<p><strong>Seven-step request lifecycle</strong> is the official study-material flow: secure transmission and context gathering, proxy filter, toxicity filtering, LLM generation, post-processing, delivery and feedback, then repeat.</p><p class=\"faint\">Exam trap: steps 1-4 are inbound and steps 5-7 are outbound. Memorize the split as much as the step names.</p>"},
  {"id": "d2", "deck": "Data & Architecture", "tag": "Lifecycle", "front": "Inbound steps", "back": "<p><strong>Inbound steps</strong> are steps 1 through 4: context gathering and secure transmission, proxy filtering, toxicity filtering, and code generation with the LLM.</p><p class=\"faint\">Do not include post-processing in inbound. Giveaway words: before model response, prompt building, injection defense, input toxicity.</p>"},
  {"id": "d3", "deck": "Data & Architecture", "tag": "Lifecycle", "front": "Outbound steps", "back": "<p><strong>Outbound steps</strong> are steps 5 through 7: post-processing and validation, suggestion delivery and feedback loop, and repeating for later prompts.</p><p class=\"faint\">Do not include initial context gathering in outbound. Giveaway words: response validation, delivered suggestion, accepted or rejected feedback.</p>"},
  {"id": "d4", "deck": "Data & Architecture", "tag": "Step 1", "front": "Step 1 secure transmission and context", "back": "<p><strong>Step 1</strong> sends the prompt over HTTPS while gathering code before and after the cursor, file metadata, adjacent tabs, paths, languages, frameworks, and FIM context.</p><p class=\"faint\">Exam trap: Step 1 is not only transport security. It is also context gathering and prompt building.</p>"},
  {"id": "d5", "deck": "Data & Architecture", "tag": "FIM", "front": "FIM in the data flow", "back": "<p><strong>Fill-in-the-Middle</strong> is part of preprocessing in Step 1 and uses both preceding and following code to build a better completion prompt.</p><p class=\"faint\">Do not confuse FIM with next edit suggestions. FIM is a prompt-building technique; next edit suggestions predict the next edit location.</p>"},
  {"id": "d6", "deck": "Data & Architecture", "tag": "Step 2", "front": "Step 2 proxy filter", "back": "<p><strong>Step 2 proxy filter</strong> sends the built prompt through a proxy server hosted in a GitHub-owned Microsoft Azure tenant to block prompt injection and jailbreak attempts.</p><p class=\"faint\">Do not confuse with Step 3 toxicity filtering. Step 2 blocks attacks on instructions; Step 3 filters harmful or personal content.</p>"},
  {"id": "d7", "deck": "Data & Architecture", "tag": "Proxy", "front": "Proxy dual role", "back": "<p><strong>Proxy dual role</strong> means the proxy protects inbound prompts from injection and jailbreaks, then helps validate outbound responses for quality, security, and public-code matching when enabled.</p><p class=\"faint\">Exam trap: the proxy appears on both legs. Inbound is attack defense; outbound is final response validation.</p>"},
  {"id": "d8", "deck": "Data & Architecture", "tag": "Step 3", "front": "Step 3 toxicity filtering", "back": "<p><strong>Step 3 toxicity filtering</strong> runs before intent extraction and filters input for categories such as hate speech, inappropriate content, and personal data.</p><p class=\"faint\">Do not confuse personal data filtering with content exclusions. Toxicity filtering is part of the request lifecycle; exclusions are repository policy.</p>"},
  {"id": "d9", "deck": "Data & Architecture", "tag": "Step 4", "front": "Step 4 LLM generation", "back": "<p><strong>Step 4</strong> is where the large language model generates the code suggestion or chat response from the filtered prompt and gathered context.</p><p class=\"faint\">Exam trap: model generation happens after inbound proxy and toxicity checks, not before them.</p>"},
  {"id": "d10", "deck": "Data & Architecture", "tag": "Step 5", "front": "Step 5 post-processing", "back": "<p><strong>Step 5 post-processing</strong> runs toxicity filtering again on the output and applies validation for code quality, common vulnerabilities, and optional matching public code.</p><p class=\"faint\">Giveaway words: XSS, SQL injection, output toxicity, public code. This is outbound validation, not initial prompt building.</p>"},
  {"id": "d11", "deck": "Data & Architecture", "tag": "Truncate", "front": "Truncate or discard", "back": "<p><strong>Truncate or discard</strong> is what happens if any part of the response fails outbound checks: the response is either shortened or not delivered.</p><p class=\"faint\">Exam trap: failing validation does not mean Copilot always asks the user to decide. The system can suppress the response.</p>"},
  {"id": "d12", "deck": "Data & Architecture", "tag": "Step 6", "front": "Step 6 delivery and feedback", "back": "<p><strong>Step 6</strong> delivers only responses that pass filters and uses accepted suggestions, modifications, and rejections as feedback signals.</p><p class=\"faint\">Do not confuse feedback with training-retention policy. The lifecycle describes product feedback, while plan rules govern whether data is excluded from training by default.</p>"},
  {"id": "d13", "deck": "Data & Architecture", "tag": "Step 7", "front": "Step 7 repeat", "back": "<p><strong>Step 7</strong> repeats the lifecycle for subsequent prompts so each turn goes through context, filtering, generation, validation, and delivery again.</p><p class=\"faint\">Exam trap: the filters are not one-time setup. They run as part of the repeated request lifecycle.</p>"},
  {"id": "d14", "deck": "Data & Architecture", "tag": "Retention", "front": "Editor completions discard prompts", "back": "<p><strong>Editor completions discard prompts</strong> means in the code editor Copilot discards prompts once a suggestion is returned.</p><p class=\"faint\">Do not confuse with Copilot Chat outside the editor, where prompts, suggestions, and supporting context are typically retained for 28 days.</p>"},
  {"id": "d15", "deck": "Data & Architecture", "tag": "Retention", "front": "28-day retention outside editor", "back": "<p><strong>28-day retention</strong> applies typically to Copilot Chat used outside the code editor, including CLI, Mobile, and Chat on GitHub.com.</p><p class=\"faint\">Exam trap: the 28-day number has an outside-the-editor qualifier. Retention within the editor may vary.</p>"},
  {"id": "d16", "deck": "Data & Architecture", "tag": "Training", "front": "Training exclusion by plan", "back": "<p><strong>Training exclusion by plan</strong> means data is excluded from training by default for Copilot Business and Copilot Enterprise, but not for Free or Pro.</p><p class=\"faint\">Do not confuse with individual opt-out. Individual subscribers can opt out of sharing prompts used to fine-tune the model.</p>"},
  {"id": "d17", "deck": "Data & Architecture", "tag": "Context", "front": "Official study material context window", "back": "<p><strong>Official study material context window</strong> states approximately 200-500 lines of code or up to a few thousand tokens.</p><p class=\"faint\">This figure is explicitly from the official study material and is outdated in the current product. Do not generalize it to today's model limits.</p>"},
  {"id": "d18", "deck": "Data & Architecture", "tag": "Context", "front": "Official study material Chat context", "back": "<p><strong>Official study material Chat context</strong> states Copilot Chat operates with a context window of 4k tokens.</p><p class=\"faint\">Exam trap: teach this as study-material wording, not as a current product claim. Current models are much larger.</p>"},
  {"id": "d19", "deck": "Data & Architecture", "tag": "Limitations", "front": "Code quality limitation", "back": "<p><strong>Code quality and correctness</strong> covers possible errors, security issues, and context misinterpretation in generated code.</p><p class=\"faint\">Do not confuse with outbound code-quality checks. The limitation is a model risk; the check is a lifecycle safeguard.</p>"},
  {"id": "d20", "deck": "Data & Architecture", "tag": "Limitations", "front": "Language specificity limitation", "back": "<p><strong>Language and framework specificity</strong> means Copilot performs differently across languages and frameworks, especially niche or underrepresented ones.</p><p class=\"faint\">Exam trap: if the issue is a less common framework, choose language and framework specificity rather than complex problem solving.</p>"},
  {"id": "d21", "deck": "Data & Architecture", "tag": "Limitations", "front": "Training data limitation", "back": "<p><strong>Dependency on training data</strong> covers bias, outdated practices, and copyright concerns arising from learned patterns.</p><p class=\"faint\">Do not confuse with customer data retention. Training-data dependency is about the model's learned source patterns.</p>"},
  {"id": "d22", "deck": "Data & Architecture", "tag": "Limitations", "front": "Complex problem-solving limitation", "back": "<p><strong>Complex problem solving</strong> covers limits in high-level design, broad architecture, and creativity constraints.</p><p class=\"faint\">Giveaway words: architecture, design strategy, novel solution. Humans should validate and lead these decisions.</p>"},
  {"id": "d23", "deck": "Data & Architecture", "tag": "Fine tuning", "front": "Target dataset and source model", "back": "<p><strong>Target dataset and source model</strong> are fine-tuning terms: the smaller target dataset adapts knowledge from a pretrained source model.</p><p class=\"faint\">Do not confuse fine-tuning with grounding. Fine-tuning changes model behavior through training; grounding adds context at request time.</p>"},
  {"id": "d24", "deck": "Data & Architecture", "tag": "LoRA", "front": "LoRA", "back": "<p><strong>LoRA</strong> adds smaller trainable parts to each layer while leaving the original model unchanged, saving time and resources.</p><p class=\"faint\">GitHub explicitly uses LoRA. Do not confuse with adapters or prefix-tuning; the brief says LoRA beats those alternatives.</p>"},
  {"id": "g1", "deck": "Prompt Engineering", "tag": "4 Ss", "front": "4 Ss framework", "back": "<p><strong>4 Ss</strong> are Single, Specific, Short, and Surround, the official study-material framework for crafting effective Copilot prompts.</p><p class=\"faint\">Exam trap: Surround is part of the framework. Do not replace it with a generic word like secure or structured.</p>"},
  {"id": "g2", "deck": "Prompt Engineering", "tag": "Single", "front": "Single prompt", "back": "<p><strong>Single</strong> means focus the prompt on one well-defined task or question.</p><p class=\"faint\">Do not confuse with Short. Single is about one task; Short is about concise wording.</p>"},
  {"id": "g3", "deck": "Prompt Engineering", "tag": "Specific", "front": "Specific prompt", "back": "<p><strong>Specific</strong> means make instructions explicit and detailed enough that Copilot knows the desired outcome, constraints, and format.</p><p class=\"faint\">Do not confuse with long. A prompt can be specific without being verbose. Giveaway words: exact, detailed, constraints.</p>"},
  {"id": "g4", "deck": "Prompt Engineering", "tag": "Short", "front": "Short prompt", "back": "<p><strong>Short</strong> means keep the prompt concise and to the point, avoiding unnecessary history or unrelated details.</p><p class=\"faint\">Exam trap: Short does not mean vague. The best prompt can be both short and specific.</p>"},
  {"id": "g5", "deck": "Prompt Engineering", "tag": "Surround", "front": "Surround prompt", "back": "<p><strong>Surround</strong> means improve context by using descriptive filenames and keeping related files open around the task.</p><p class=\"faint\">Do not confuse with adding examples. Surround is about environmental context, especially relevant files and names.</p>"},
  {"id": "g6", "deck": "Prompt Engineering", "tag": "Zero-shot", "front": "Zero-shot prompting", "back": "<p><strong>Zero-shot prompting</strong> asks Copilot to perform a task without providing examples in the prompt.</p><p class=\"faint\">Do not confuse with one-shot or few-shot. Giveaway words: no examples, direct instruction only.</p>"},
  {"id": "g7", "deck": "Prompt Engineering", "tag": "One-shot", "front": "One-shot prompting", "back": "<p><strong>One-shot prompting</strong> provides exactly one example of the desired input-output pattern before asking Copilot to complete a similar task.</p><p class=\"faint\">Exam trap: the study guide names zero-shot and few-shot, but the training defines one-shot. One example means one-shot.</p>"},
  {"id": "g8", "deck": "Prompt Engineering", "tag": "Few-shot", "front": "Few-shot prompting", "back": "<p><strong>Few-shot prompting</strong> provides multiple examples so Copilot can infer the desired style, structure, or transformation.</p><p class=\"faint\">Do not confuse with chain prompting. Few-shot teaches by examples; chain prompting breaks work into sequential prompts.</p>"},
  {"id": "g9", "deck": "Prompt Engineering", "tag": "Role", "front": "Role prompting", "back": "<p><strong>Role prompting</strong> asks Copilot to respond as a particular expert or specialist, such as a security expert, tester, or performance optimizer.</p><p class=\"faint\">Exam trap: role prompting changes perspective and focus; it does not grant permissions or bypass safeguards.</p>"},
  {"id": "g10", "deck": "Prompt Engineering", "tag": "Chain", "front": "Chain prompting", "back": "<p><strong>Chain prompting</strong> breaks a larger task into a sequence of smaller prompts, using each answer to guide the next step.</p><p class=\"faint\">Do not confuse with chat history management. Chain prompting is a deliberate workflow; history management controls how much context remains useful.</p>"},
  {"id": "g11", "deck": "Prompt Engineering", "tag": "History", "front": "Chat history management", "back": "<p><strong>Chat history management</strong> means managing prior turns so Copilot has relevant context without overloading the prompt with stale or distracting information.</p><p class=\"faint\">Exam trap: more history is not always better. Long prompts consume GitHub AI Credits and can bury the important context.</p>"},
  {"id": "g12", "deck": "Prompt Engineering", "tag": "Context", "front": "Context crafting", "back": "<p><strong>Context crafting</strong> means supplying files, selected code, examples, instructions, and constraints that help Copilot answer the actual task.</p><p class=\"faint\">Do not confuse with fine-tuning. Context crafting changes a single request; fine-tuning changes a model through training.</p>"},
  {"id": "g13", "deck": "Prompt Engineering", "tag": "Instructions", "front": "Instruction precedence overview", "back": "<p><strong>Instruction precedence</strong> is personal instructions first, repository custom instructions second, and organization custom instructions third.</p><p class=\"faint\">Exam trap: organization ranks lowest for instructions even though organization or enterprise settings can win for policies.</p>"},
  {"id": "g14", "deck": "Prompt Engineering", "tag": "Instructions", "front": "Personal instructions precedence", "back": "<p><strong>Personal instructions</strong> have the highest precedence among custom instructions and are only supported for Copilot Chat on GitHub.com.</p><p class=\"faint\">Do not confuse personal instructions with personal policy settings. A user with an org-assigned seat inherits some policies from the org.</p>"},
  {"id": "g15", "deck": "Prompt Engineering", "tag": "Instructions", "front": "Repository instruction precedence", "back": "<p><strong>Repository custom instructions</strong> rank below personal instructions and above organization instructions.</p><p class=\"faint\">Exam trap: repository guidance can include path-specific files, repository-wide instructions, and AGENTS.md.</p>"},
  {"id": "g16", "deck": "Prompt Engineering", "tag": "Instructions", "front": "Organization instructions precedence", "back": "<p><strong>Organization custom instructions</strong> rank lowest among instruction types but still apply to all organization members where supported.</p><p class=\"faint\">Do not confuse instruction precedence with policy enforcement. For policies, organizations and enterprises can override user choice.</p>"},
  {"id": "g17", "deck": "Prompt Engineering", "tag": "Path-specific", "front": "Path-specific instructions", "back": "<p><strong>Path-specific instructions</strong> live in .github/instructions/NAME.instructions.md and rank above repository-wide instructions for relevant paths.</p><p class=\"faint\">Exam trap: path-specific beats repo-wide within repository instructions. File location and matching path matter.</p>"},
  {"id": "g18", "deck": "Prompt Engineering", "tag": "Repo-wide", "front": "Repository-wide instructions", "back": "<p><strong>Repository-wide instructions</strong> live in .github/copilot-instructions.md and provide general guidance for the repository.</p><p class=\"faint\">Do not confuse with AGENTS.md. Both are repository instruction sources, but path-specific instructions outrank repo-wide guidance.</p>"},
  {"id": "g19", "deck": "Prompt Engineering", "tag": "Agents", "front": "AGENTS.md", "back": "<p><strong>AGENTS.md</strong> is the agent-instructions file included in the repository custom instruction set.</p><p class=\"faint\">Exam trap: AGENTS.md is below path-specific and repository-wide instruction entries in the listed repository instruction order.</p>"},
  {"id": "g20", "deck": "Prompt Engineering", "tag": "Policy trap", "front": "Instructions vs policies", "back": "<p><strong>Instructions vs policies</strong> differ because instructions guide Copilot responses, while policies enforce access, feature availability, and privacy settings.</p><p class=\"faint\">Giveaway trap: organization is lowest for instructions, but organization or enterprise can win for policies. Do not apply one precedence rule to both.</p>"},
  {"id": "g21", "deck": "Prompt Engineering", "tag": "Prompt files", "front": "Prompt files", "back": "<p><strong>Prompt files</strong> are reusable prompts stored at .github/prompts/*.prompt.md for consistent responses and workflows.</p><p class=\"faint\">Do not confuse prompt files with custom instructions. Prompt files are invoked for a task; instructions are standing guidance.</p>"},
  {"id": "g22", "deck": "Prompt Engineering", "tag": "Non-determinism", "front": "Instructions are non-deterministic", "back": "<p><strong>Custom instructions</strong> may not be followed identically every time because Copilot output is non-deterministic.</p><p class=\"faint\">Exam trap: instructions improve behavior but are not hard enforcement. Use policies for enforceable controls.</p>"},
  {"id": "g23", "deck": "Prompt Engineering", "tag": "Open files", "front": "Keeping related files open", "back": "<p><strong>Keeping related files open</strong> supports the Surround principle by giving Copilot nearby project context such as related files, tabs, and paths.</p><p class=\"faint\">Do not confuse with content exclusions. Open files add context; exclusions prevent affected content from informing Copilot where supported.</p>"},
  {"id": "g24", "deck": "Prompt Engineering", "tag": "Credits", "front": "Prompt length and credits", "back": "<p><strong>Prompt length</strong> matters because long prompts and full chat history consume more GitHub AI Credits and context budget.</p><p class=\"faint\">The old study material may mention PRU terminology, but the current term is GitHub AI Credits. Use the current term.</p>"},
  {"id": "y1", "deck": "Productivity", "tag": "SDLC", "front": "Copilot across the SDLC", "back": "<p><strong>Copilot across the SDLC</strong> helps across planning, coding, testing, reviewing, documenting, debugging, refactoring, securing, and modernizing software.</p><p class=\"faint\">Exam trap: Copilot is not only a code-completion tool. Domain 5 expects productivity and quality across the development lifecycle.</p>"},
  {"id": "y2", "deck": "Productivity", "tag": "Generation", "front": "Code generation", "back": "<p><strong>Code generation</strong> uses Copilot to draft functions, classes, scripts, and implementation details from natural-language intent and project context.</p><p class=\"faint\">Do not confuse generation with validation. Generated code remains a draft that needs review and tests.</p>"},
  {"id": "y3", "deck": "Productivity", "tag": "Testing", "front": "Test generation", "back": "<p><strong>Test generation</strong> uses Copilot to create unit tests, integration tests, edge cases, and assertions from existing code and expected behavior.</p><p class=\"faint\">Exam trap: asking for tests does not prove correctness. Run the tests and inspect whether edge cases and assertions are meaningful.</p>"},
  {"id": "y4", "deck": "Productivity", "tag": "Docs", "front": "Documentation generation", "back": "<p><strong>Documentation generation</strong> uses Copilot to draft comments, READMEs, API descriptions, and explanations that reduce context switching.</p><p class=\"faint\">Do not confuse documentation with transparency as an AI principle. Documentation improves developer productivity; transparency explains AI behavior and limits.</p>"},
  {"id": "y5", "deck": "Productivity", "tag": "Debugging", "front": "Debugging assistance", "back": "<p><strong>Debugging assistance</strong> uses Copilot to explain errors, inspect stack traces, propose causes, and suggest fixes.</p><p class=\"faint\">Exam trap: Copilot can help reason about a bug, but the developer must reproduce and verify the fix.</p>"},
  {"id": "y6", "deck": "Productivity", "tag": "Refactoring", "front": "Refactoring", "back": "<p><strong>Refactoring</strong> uses Copilot to improve code structure, readability, maintainability, or design without changing intended behavior.</p><p class=\"faint\">Do not confuse refactoring with modernization. Refactoring can stay on the same platform; modernization moves older code toward newer APIs or patterns.</p>"},
  {"id": "y7", "deck": "Productivity", "tag": "Modernization", "front": "Modernization", "back": "<p><strong>Modernization</strong> uses Copilot to update legacy code, replace outdated practices, and move toward current frameworks or patterns.</p><p class=\"faint\">Exam trap: modernization still needs human review for architecture, compatibility, and rollout risk.</p>"},
  {"id": "y8", "deck": "Productivity", "tag": "Learning", "front": "Accelerated learning", "back": "<p><strong>Accelerated learning</strong> means Copilot can explain unfamiliar code, APIs, frameworks, or patterns so developers ramp faster.</p><p class=\"faint\">Do not confuse with training the model. The developer learns from Copilot; the model is not necessarily fine-tuned.</p>"},
  {"id": "y9", "deck": "Productivity", "tag": "Context switching", "front": "Reduced context switching", "back": "<p><strong>Reduced context switching</strong> means developers can ask Copilot for explanations, commands, tests, or summaries without leaving their workflow.</p><p class=\"faint\">Exam trap: productivity gains include focus and flow, not only more accepted lines of code.</p>"},
  {"id": "y10", "deck": "Productivity", "tag": "Sample data", "front": "Sample data generation", "back": "<p><strong>Sample data generation</strong> uses Copilot to create representative test data, fixtures, and examples for development and testing.</p><p class=\"faint\">Do not confuse sample data with production data. Avoid sensitive or real personal data in prompts and fixtures.</p>"},
  {"id": "y11", "deck": "Productivity", "tag": "Security", "front": "Security improvements", "back": "<p><strong>Security improvements</strong> include asking Copilot to identify vulnerabilities, suggest safer patterns, and improve handling of inputs or secrets.</p><p class=\"faint\">Do not confuse with Copilot Autofix. General security prompting helps developers; Autofix is tied to CodeQL code scanning alerts.</p>"},
  {"id": "y12", "deck": "Productivity", "tag": "Performance", "front": "Performance optimization", "back": "<p><strong>Performance optimization</strong> uses Copilot to identify inefficient code paths and suggest improvements while preserving intended behavior.</p><p class=\"faint\">Exam trap: a faster suggestion still needs benchmarking and tests. Copilot output is not proof of performance.</p>"},
  {"id": "y13", "deck": "Productivity", "tag": "Autofix", "front": "Copilot Autofix", "back": "<p><strong>Copilot Autofix</strong> automatically generates fix suggestions for CodeQL alerts on pull requests and the default branch.</p><p class=\"faint\">Do not confuse with Copilot code review. Autofix is driven by CodeQL code scanning alerts and includes proposed code changes.</p>"},
  {"id": "y14", "deck": "Productivity", "tag": "Autofix", "front": "Autofix subscription trap", "back": "<p><strong>Copilot Autofix</strong> does not require a GitHub Copilot subscription for CodeQL analysis.</p><p class=\"faint\">This is a high-value exam trap. Never state that Copilot Autofix requires a Copilot subscription; it does not.</p>"},
  {"id": "y15", "deck": "Productivity", "tag": "Autofix", "front": "Autofix inputs", "back": "<p><strong>Copilot Autofix inputs</strong> include CodeQL alert data in SARIF format, surrounding code snippets, and query help text.</p><p class=\"faint\">Do not confuse with arbitrary chat context. Autofix works from structured code scanning alert data.</p>"},
  {"id": "y16", "deck": "Productivity", "tag": "Autofix", "front": "Autofix suggestion contents", "back": "<p><strong>Autofix suggestions</strong> include both a code change and a natural-language explanation.</p><p class=\"faint\">Exam trap: Autofix is not just a comment or summary. It proposes a patch and explains it.</p>"},
  {"id": "y17", "deck": "Productivity", "tag": "Security", "front": "Generic secret detection", "back": "<p><strong>Generic secret detection</strong> is an AI security feature that does not require a GitHub Copilot subscription.</p><p class=\"faint\">Do not group every AI-labeled security feature under Copilot licensing. The brief explicitly lists this as not requiring Copilot.</p>"},
  {"id": "y18", "deck": "Productivity", "tag": "Security", "front": "Custom pattern regex generator", "back": "<p><strong>Custom pattern regex generator</strong> helps create secret-scanning custom patterns and does not require a GitHub Copilot subscription.</p><p class=\"faint\">Exam trap: the regex generator is distinct from Copilot Chat and from Copilot Autofix, but it shares the no-Copilot-subscription fact.</p>"},
  {"id": "y19", "deck": "Productivity", "tag": "Quality", "front": "GitHub Code Quality", "back": "<p><strong>GitHub Code Quality</strong> is another AI security or quality feature listed as not requiring a GitHub Copilot subscription.</p><p class=\"faint\">Do not confuse GitHub Code Quality with Copilot code review. The subscription requirement fact is the tested contrast.</p>"},
  {"id": "y20", "deck": "Productivity", "tag": "Metrics", "front": "Average Daily Active Users", "back": "<p><strong>Average Daily Active Users</strong> is a named Copilot impact metric for measuring how many users actively use Copilot on an average day.</p><p class=\"faint\">Do not confuse with seat count. Active users measure usage; seats measure assignment or entitlement.</p>"},
  {"id": "y21", "deck": "Productivity", "tag": "Metrics", "front": "Total Acceptance Rate", "back": "<p><strong>Total Acceptance Rate</strong> is a named Copilot impact metric that measures accepted suggestions relative to suggestions shown.</p><p class=\"faint\">Exam trap: acceptance rate is not the same as lines of code accepted. One measures rate; the other measures volume.</p>"},
  {"id": "y22", "deck": "Productivity", "tag": "Metrics", "front": "Lines of Code Accepted", "back": "<p><strong>Lines of Code Accepted</strong> is a named Copilot impact metric tracking the amount of suggested code developers accept.</p><p class=\"faint\">Do not treat accepted lines as the only productivity signal. Pair with usage and survey data to avoid a narrow metric.</p>"},
  {"id": "y23", "deck": "Productivity", "tag": "Stages", "front": "Four productivity stages", "back": "<p><strong>Four productivity stages</strong> are Evaluation, Adoption, Optimization, and Sustained efficiency.</p><p class=\"faint\">Exam trap: memorize the order. Evaluation comes before broad adoption; sustained efficiency is the ongoing mature state.</p>"},
  {"id": "y24", "deck": "Productivity", "tag": "Measurement", "front": "Usage metrics API and survey", "back": "<p><strong>Usage metrics sources</strong> include the REST API for Copilot usage metrics and the GitHub Copilot Developer Survey.</p><p class=\"faint\">The survey cadence matters: short form every two weeks and long form no more than once every four weeks.</p>"},
  {"id": "s1", "deck": "Privacy & Safeguards", "tag": "Plans", "front": "Seven Copilot plans", "back": "<p><strong>Seven Copilot plans</strong> are Copilot Free, Copilot Student, Copilot Pro, Copilot Pro+, Copilot Max, Copilot Business, and Copilot Enterprise.</p><p class=\"faint\">Exam trap: the study-source plan lineup may be older. Current content uses seven plans, not four.</p>"},
  {"id": "s2", "deck": "Privacy & Safeguards", "tag": "GHES", "front": "GitHub Enterprise Server availability", "back": "<p><strong>GitHub Enterprise Server</strong> does not currently support GitHub Copilot.</p><p class=\"faint\">This is an outright ban in the brief: never describe Copilot as available for GitHub Enterprise Server.</p>"},
  {"id": "s3", "deck": "Privacy & Safeguards", "tag": "Exclusions", "front": "Content exclusions availability", "back": "<p><strong>Content exclusions</strong> are available only for Copilot Business and Copilot Enterprise.</p><p class=\"faint\">Do not confuse with all paid individual plans. Pro, Pro+, and Max do not get content exclusion in the brief.</p>"},
  {"id": "s4", "deck": "Privacy & Safeguards", "tag": "Exclusions", "front": "What content exclusions do", "back": "<p><strong>Content exclusions</strong> prevent inline suggestions in affected files, stop affected content from informing suggestions or responses, and exclude affected files from Copilot code review.</p><p class=\"faint\">Exam trap: exclusions affect multiple Copilot surfaces, not just inline completion availability.</p>"},
  {"id": "s5", "deck": "Privacy & Safeguards", "tag": "Exclusions", "front": "Who configures exclusions", "back": "<p><strong>Content exclusions</strong> can be configured by repository administrators for their repositories, organization owners for org-seated users, and enterprise owners.</p><p class=\"faint\">Do not confuse with personal custom instructions. Exclusions are an administrative privacy safeguard.</p>"},
  {"id": "s6", "deck": "Privacy & Safeguards", "tag": "Exclusions", "front": "Repository URL policy lookup", "back": "<p><strong>Repository URL policy lookup</strong> sends only the repository URL so the server can return the correct content exclusion policy, and those URLs are not logged.</p><p class=\"faint\">Exam trap: the server does not need file contents just to fetch the exclusion policy.</p>"},
  {"id": "s7", "deck": "Privacy & Safeguards", "tag": "Limits", "front": "Semantic leakage limit", "back": "<p><strong>Semantic leakage</strong> can still occur because Copilot may receive IDE-provided semantic information from excluded files, such as type info, hover definitions, or build configuration.</p><p class=\"faint\">Do not overstate exclusions. They block file content where supported, but they do not stop indirect IDE semantic context.</p>"},
  {"id": "s8", "deck": "Privacy & Safeguards", "tag": "Limits", "front": "Symlink and remote filesystem limit", "back": "<p><strong>Symlink and remote filesystem limit</strong> means content exclusions do not apply to symbolic links or repositories located on remote filesystems.</p><p class=\"faint\">Exam trap: a path pattern is not a universal data boundary. Symlinks and remote filesystems are explicit limits.</p>"},
  {"id": "s9", "deck": "Privacy & Safeguards", "tag": "Limits", "front": "Edit and Agent mode limit", "back": "<p><strong>Edit and Agent mode limit</strong> means content exclusion is not currently supported in Edit and Agent modes of Copilot Chat in VS Code and other editors.</p><p class=\"faint\">Do not assume exclusions apply in every Copilot mode. This limitation is one of the richest exam traps.</p>"},
  {"id": "s10", "deck": "Privacy & Safeguards", "tag": "Support", "front": "Content exclusion support matrix", "back": "<p><strong>Content exclusion support matrix</strong> differs by surface: inline exclusions cover many editors, while chat and agent support excludes Xcode and Eclipse.</p><p class=\"faint\">Exam trap: support for inline suggestions in an editor does not imply chat or agent exclusion support there.</p>"},
  {"id": "s11", "deck": "Privacy & Safeguards", "tag": "Public code", "front": "Suggestions matching public code", "back": "<p><strong>Suggestions matching public code</strong> is the current privacy setting with values Allow and Block for filtering suggestions that match public code.</p><p class=\"faint\">The old duplication detection wording is history. Do not build an item around the disputed exact matching-length interpretation.</p>"},
  {"id": "s12", "deck": "Privacy & Safeguards", "tag": "Public code", "front": "Allow vs Block", "back": "<p><strong>Allow vs Block</strong> controls whether public-code-matching suggestions can be shown or are blocked when the matching safeguard applies.</p><p class=\"faint\">Exam trap: Block is required for GitHub to assume IP indemnity responsibility under Business and Enterprise.</p>"},
  {"id": "s13", "deck": "Privacy & Safeguards", "tag": "Public code", "front": "Only public GitHub code searched", "back": "<p><strong>Only public GitHub code searched</strong> means the matching process searches public repositories on GitHub.com, not private GitHub repositories or code outside GitHub.</p><p class=\"faint\">Do not confuse with private-code leakage. The public-code matching index is about public code only.</p>"},
  {"id": "s14", "deck": "Privacy & Safeguards", "tag": "Public code", "front": "Accepted unmodified suggestions checked", "back": "<p><strong>Accepted unmodified suggestions checked</strong> means code you wrote yourself and Copilot suggestions you altered are not checked for matches to public code.</p><p class=\"faint\">Exam trap: the safeguard targets Copilot candidate suggestions and accepted unmodified suggestions, not every line in your project.</p>"},
  {"id": "s15", "deck": "Privacy & Safeguards", "tag": "Public code", "front": "Index staleness", "back": "<p><strong>Index staleness</strong> means the public-code matching index refreshes every few months, so very new or deleted public code may not be represented.</p><p class=\"faint\">Do not treat the setting as a perfect copyright detector. It is a safeguard with documented limits.</p>"},
  {"id": "s16", "deck": "Privacy & Safeguards", "tag": "Locked toggle", "front": "Org-assigned locked toggle", "back": "<p><strong>Org-assigned locked toggle</strong> means a user whose Copilot seat is assigned by an organization cannot change Suggestions matching public code in personal settings; it reflects org or enterprise policy.</p><p class=\"faint\">Exam trap: personal settings apply only when the user controls their own seat. Org-assigned seats inherit the organization setting.</p>"},
  {"id": "s17", "deck": "Privacy & Safeguards", "tag": "Indemnity", "front": "IP indemnity", "back": "<p><strong>IP indemnity</strong> is included with Copilot Business and Copilot Enterprise when Suggestions matching public code is set to Block.</p><p class=\"faint\">Do not omit either condition. Business or Enterprise alone is not enough under the brief; Block is also required.</p>"},
  {"id": "s18", "deck": "Privacy & Safeguards", "tag": "Contracts", "front": "Three contractual protections", "back": "<p><strong>Three contractual protections</strong> are IP indemnity, the Data Protection Agreement, and the GitHub Copilot Trust Center.</p><p class=\"faint\">Exam trap: these are contractual or trust protections, not feature modes like Agent mode or Spaces.</p>"},
  {"id": "s19", "deck": "Privacy & Safeguards", "tag": "Policies", "front": "Same enterprise conflict rule", "back": "<p><strong>Same enterprise conflict rule</strong> usually applies the least restrictive policy when a user is in multiple organizations within one enterprise.</p><p class=\"faint\">This is easy to reverse. Least restrictive is within one enterprise; most restrictive is across different enterprises.</p>"},
  {"id": "s20", "deck": "Privacy & Safeguards", "tag": "Policies", "front": "Different enterprises conflict rule", "back": "<p><strong>Different enterprises conflict rule</strong> almost always applies the most restrictive policy when multiple different enterprises affect a user.</p><p class=\"faint\">Example trap: if any enterprise disables Copilot Chat in GitHub, it is disabled for that user.</p>"},
  {"id": "s21", "deck": "Privacy & Safeguards", "tag": "Policies", "front": "Organization policies vs personal plans", "back": "<p><strong>Organization policies</strong> can govern org-assigned users, and an individual plan is cancelled when the user is added to Business or Enterprise.</p><p class=\"faint\">Do not invent a conflict between a personal plan and org policy. The brief says the individual plan is cancelled.</p>"},
  {"id": "s22", "deck": "Privacy & Safeguards", "tag": "Audit", "front": "Audit logs do not capture prompts", "back": "<p><strong>Audit logs</strong> do not include client session data such as prompts a user sends to Copilot locally.</p><p class=\"faint\">Exam trap: audit logs record settings, policies, license events, and website agent activity, not local prompt text.</p>"},
  {"id": "s23", "deck": "Privacy & Safeguards", "tag": "Audit", "front": "Audit log retention", "back": "<p><strong>Audit log retention</strong> is 180 days for Copilot audit log history unless streamed elsewhere for longer retention.</p><p class=\"faint\">Do not assert other retention durations beyond confirmed facts. For longer history, stream to a SIEM.</p>"},
  {"id": "s24", "deck": "Privacy & Safeguards", "tag": "Audit", "front": "Querying Copilot audit events", "back": "<p><strong>Querying Copilot audit events</strong> can use action:copilot for Copilot events and actor:Copilot for agent activity.</p><p class=\"faint\">Do not confuse actor:Copilot with the human user. Agentic audit fields include actor_is_agent and agent_session_id.</p>"},
  {"id": "s25", "deck": "Privacy & Safeguards", "tag": "Plans", "front": "Free and Student model access", "back": "<p><strong>Free and Student model access</strong> uses Auto model selection only.</p><p class=\"faint\">Exam trap: model access differs by plan, but do not study or name specific model version numbers.</p>"},
  {"id": "s26", "deck": "Privacy & Safeguards", "tag": "Plans", "front": "Free plan eligibility", "back": "<p><strong>Copilot Free eligibility</strong> is limited to individual developers who do not have Copilot through an organization or enterprise.</p><p class=\"faint\">Do not confuse Free with Business or Enterprise assignment. Organization access changes the user's plan situation and policy control.</p>"},
];
